def make_event(**overrides: Any) -> dict[str, Any]:
    event: dict[str, Any] = {
        "eventId": "evt-1",
        "organizationId": "org-1",
        "type": "incident.created",
        "occurredAt": 100,
        "payload": {"region": "north"},
    }
    event.update(overrides)
    return event


class RegionAlertTest(unittest.TestCase):
    def setUp(self) -> None:
        self.server = create_server(port=0)
        self.thread = threading.Thread(target=self.server.serve_forever, daemon=True)
        self.thread.start()
        self.base_url = f"http://127.0.0.1:{self.server.server_port}"
        self.token_cache: dict[str, str] = {}

    def tearDown(self) -> None:
        self.server.shutdown()
        self.server.server_close()
        self.thread.join(timeout=2)

    def request_raw(
        self,
        path: str,
        *,
        method: str = "GET",
        body: bytes | None = None,
        content_type: str | None = "application/json",
        auth: bool = True,
        token: str | None = None,
    ) -> tuple[int, bytes, Any]:
        headers = {}
        if content_type is not None:
            headers["Content-Type"] = content_type
        if token is not None:
            headers["Authorization"] = f"Bearer {token}"
        elif auth:
            headers.update(
                _support.authorization_header(
                    self.token_cache, self.base_url, path, body
                )
            )
        request = Request(
            f"{self.base_url}{path}",
            data=body,
            headers=headers,
            method=method,
        )
        try:
            with urlopen(request, timeout=5) as response:
                raw = response.read()
                return response.status, raw, json.loads(raw)
        except HTTPError as error:
            raw = error.read()
            try:
                return error.code, raw, json.loads(raw)
            finally:
                error.close()

    def request(
        self,
        path: str,
        *,
        method: str = "GET",
        body: bytes | None = None,
        content_type: str | None = "application/json",
    ) -> tuple[int, Any]:
        status, _, parsed = self.request_raw(
            path, method=method, body=body, content_type=content_type
        )
        return status, parsed

    def post_json(self, path: str, payload: Any) -> tuple[int, Any]:
        return self.request(path, method="POST", body=json.dumps(payload).encode())

    def post_event(self, event: dict[str, Any]) -> tuple[int, Any]:
        return self.post_json("/events", event)

    def alert_payload(self, **overrides: Any) -> dict[str, Any]:
        payload: dict[str, Any] = {
            "organizationId": "org-1",
            "region": "north",
            "type": "incident.created",
            "windowSize": 60,
            "threshold": 2,
            "suppressionWindow": 100,
        }
        payload.update(overrides)
        return payload

    def evaluate_alert(self, **overrides: Any) -> tuple[int, Any]:
        return self.post_json(
            "/alerts/region/evaluate", self.alert_payload(**overrides)
        )

    def list_alerts(
        self, query: str = "organizationId=org-1&region=north"
    ) -> tuple[int, Any]:
        suffix = f"?{query}" if query else ""
        return self.request(f"/alerts/region{suffix}")

    def seed_events(self, *timestamps: int, **overrides: Any) -> None:
        for index, timestamp in enumerate(timestamps):
            self.assertEqual(
                self.post_event(
                    make_event(eventId=f"evt-{index}", occurredAt=timestamp)
                )[0],
                201,
            )

    # ------------------------------------------------------------- escalation

    def test_below_threshold_is_observe_with_null_identity(self) -> None:
        self.seed_events(10)
        status, body = self.evaluate_alert(threshold=2)
        self.assertEqual(status, 200)
        self.assertEqual(
            body,
            {
                "organizationId": "org-1",
                "region": "north",
                "type": "incident.created",
                "windowSize": 60,
                "threshold": 2,
                "suppressionWindow": 100,
                "from": None,
                "to": None,
                "peakStart": 0,
                "peakCount": 1,
                "action": "observe",
                "alertId": None,
                "suppressedCount": None,

        """Return True when the subject's organization matches the request."""
        if subject.organization_id != organization_id:
            self._forbidden(newline=newline)
            return False
        return True

    def _allow_branch(
        self, subject: Subject, branch: Branch, *, newline: bool = True
    ) -> bool:
        """Return True when the branch belongs to the subject's organization."""
        return self._authorize_organization(
            subject, branch.organization_id, newline=newline
        )

    def _unauthorized(self, *, newline: bool = True) -> None:
        self._write_json(
            HTTPStatus.UNAUTHORIZED,
            {"error": "unauthorized"},
            newline=newline,
        )

    def _forbidden(self, *, newline: bool = True) -> None:
        self._write_json(
            HTTPStatus.FORBIDDEN,
            {"error": "forbidden"},
            newline=newline,
        )

    def _json_request_body(
        self, *, newline: bool = False, reject_duplicate_keys: bool = False
    ) -> Any:
        """Validate the media type and decode the request body as JSON.

        On failure the 415/400 response is written here and the ``_BODY_ERROR``
        sentinel is returned; callers must return immediately. A duplicated
        JSON field is syntactically valid JSON, so when
        ``reject_duplicate_keys`` is set (an entry point whose contract makes
        a repeated field a validation failure) it is reported here as the 422
        validation error rather than the 400 syntax error.
        """
        content_type = self.headers.get("Content-Type", "")
        media_type = content_type.split(";", 1)[0].strip().lower()
        if media_type != "application/json":
            self._write_json(
                HTTPStatus.UNSUPPORTED_MEDIA_TYPE,
                {"error": "unsupported_media_type"},
                newline=newline,
            )
            return _BODY_ERROR

        try:
            length = int(self.headers.get("Content-Length", 0))
        except (TypeError, ValueError):
            length = 0
        raw_body = self.rfile.read(length) if length > 0 else b""
        try:
            decoded = raw_body.decode("utf-8")
        except UnicodeDecodeError:
            self._write_json(
                HTTPStatus.BAD_REQUEST,
                {"error": "invalid_json"},
                newline=newline,
            )
            return _BODY_ERROR
        try:
            return json.loads(
                decoded,
                object_pairs_hook=(
                    _reject_duplicate_keys if reject_duplicate_keys else None
                ),
            )
        except DuplicateJsonKeyError as exc:
            self._write_json(
                HTTPStatus.UNPROCESSABLE_ENTITY,
                {"error": "validation_error", "message": str(exc)},
                newline=newline,
            )
            return _BODY_ERROR
        except json.JSONDecodeError:
            self._write_json(
                HTTPStatus.BAD_REQUEST,
                {"error": "invalid_json"},
                newline=newline,
            )
            return _BODY_ERROR

    def _write_json(
        self, status: HTTPStatus, payload: dict[str, Any], *, newline: bool = False
    ) -> None:
        body = json.dumps(payload, separators=(",", ":"), sort_keys=True).encode()
        if newline:
            body += b"\n"
        self.send_response(status.value)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def log_message(self, format: str, *args: Any) -> None:
        return


def create_server(host: str = "127.0.0.1", port: int = 8000) -> ThreadingHTTPServer:
    server = ThreadingHTTPServer((host, port), Handler)
    server.tokens = TokenRegistry()  # type: ignore[attr-defined]
    server.ledger = EventLedger()  # type: ignore[attr-defined]
    server.reservations = ReservationInventory()  # type: ignore[attr-defined]
    server.snapshots = SnapshotStore()  # type: ignore[attr-defined]
    server.branches = BranchStore()  # type: ignore[attr-defined]
    server.alerts = AlertStore()  # type: ignore[attr-defined]
    return server


def serve(host: str = "127.0.0.1", port: int = 8000) -> None:
    server = create_server(host, port)
    try:
        print(f"{SERVICE_NAME} listening on http://{host}:{server.server_port}")
        server.serve_forever()
    except KeyboardInterrupt:
        pass

